INSERT INTO `news_sentiment` (`id`, `ts_code`, `pub_date`, `title`, `content`, `sentiment_score`, `sentiment_label`, `source`) VALUES (34, '600267.SH', '2026-04-15 12:19:00', '600267，直线拉涨停！', '【导读】A股三大指数涨跌不一，GPU板块强势走高，医药板块多股涨停 4月15日上午，A股三大指数集体高开，创业板指盘中刷新十年新高，随后震荡调整。截至午间收盘，沪指涨0.37%，深成指跌0.25%，创业板指跌0.23%，科创综指涨1.47%。 从板块上看，GPU板块强势走高', 0.5233, '中性', '中国基金报');
INSERT INTO `news_sentiment` (`id`, `ts_code`, `pub_date`, `title`, `content`, `sentiment_score`, `sentiment_label`, `source`) VALUES (35, '600267.SH', '2026-05-21 16:49:00', '海正药业：获得阿帕他胺片药品注册证书', '人民财讯5月21日电，海正药业6002675月21日公告，公司于近日收到国家药监局核准签发的阿帕他胺片《药品注册证书》。阿帕他胺片适用于转移性内分泌治疗敏感性前列腺癌（mHSPC）成年患者；有高危转移风险的非转移性去势抵抗前列腺癌（NM-CRPC）成年患者。', 0.0476, '负面', '证券时报网');
INSERT INTO `news_sentiment` (`id`, `ts_code`, `pub_date`, `title`, `content`, `sentiment_score`, `sentiment_label`, `source`) VALUES (36, '600267.SH', '2026-05-21 19:49:07', '海正药业：阿帕他胺片获药品注册证书 用于前列腺癌治疗', '中证智能财讯海正药业（600267）5月21日晚间公告，公司近日收到国家药品监督管理局核准签发的阿帕他胺片《药品注册证书》，该药品按化学药品4类获批境内生产，视同通过仿制药质量和疗效一致性评价。', 0.1058, '负面', '中国证券报·中证网');
INSERT INTO `news_sentiment` (`id`, `ts_code`, `pub_date`, `title`, `content`, `sentiment_score`, `sentiment_label`, `source`) VALUES (37, '600267.SH', '2026-05-22 16:30:00', '动物疫苗概念下跌0.47%，主力资金净流出11股', '600420 国药现代 -0.33 0.30 -32.38 000735 罗牛山 1.02 1.09 -1.54 688098 申联生物 1.60 0.38 4.28 300841 康华生物 -1.89 2.27 57.88 603739 蔚蓝生物 0.29 1.58 65.69 600267', 0.9853, '正面', '证券时报网');
INSERT INTO `news_sentiment` (`id`, `ts_code`, `pub_date`, `title`, `content`, `sentiment_score`, `sentiment_label`, `source`) VALUES (38, '600267.SH', '2026-05-18 16:22:00', '因海正药业年报审计违规 天健会计师事务所及两注会被警示', '该决定是由于在对海正药业（600267）2021年和2022年年报审计及内部控制审计项目中存在多项审计失误。 具体问题包括未对贸易业务是否适用总额法保持职业怀疑、控制测试范围不完整、细节测试执行不到位、存货监盘范围不完整以及个别函证未保持控制。', 0.685, '正面', '财中社');
INSERT INTO `news_sentiment` (`id`, `ts_code`, `pub_date`, `title`, `content`, `sentiment_score`, `sentiment_label`, `source`) VALUES (39, '600267.SH', '2026-05-18 17:49:46', '海正药业年报审计违规！天健会计师事务所及两名注册会计师被警示', '5月18日，据中国证监会浙江监管局消息，由于在海正药业6002672021年和2022年审计项目中存在多项失误，天健会计师事务所（特殊普通合伙）（下称“天健所”）及注册会计师俞佳南、刘壮被采取出具警示函的监督管理措施，并记入证券期货市场诚信档案。', 0.5793, '中性', '深圳商报·读创');
